// Ported from dmd/common/bitfields.d unittest (bitfields.d:122-162).
//
// The upstream unittest exercises the CODE GENERATED by `mixin(generateBitFields!(B, ushort))`
// inside `struct S`. Per 07-compile-time.md the mixin is resolved at translation time: here we
// materialize the CONCRETE accessors the generator produces for `B`, exactly as a consumer file
// would emit them, and drive them with the upstream assertions verbatim.
//
// The resolved layout for `B` (VERIFIED via ldc2 /tmp/probe_bitfields.d):
//   B members:  x(bool) y(bool) e(E) z(bool) w(ubyte=77)   with defaults  e=E.c, z=1, w=77
//   bit layout: x@0/1b  y@1/1b  e@2/2b(mask 3)  z@4/1b  w@5/8b(mask 255)
//   storage:    `ushort bitFields` initialized to 2488  (e.c<<2 | z<<4 | w<<5 = 8|16|2464)
// The accessors below are the literal shift/mask translation of that resolved code, routed
// through the tested `bitFieldGet`/`bitFieldSet` primitives.

import { describe, test, expect } from "vitest";
import { bitFieldGet, bitFieldSet } from "./bitfields.js";

// resolved: enum E { a, b, c, } (bitfields.d:124) -> the unittest's local enum.
enum E {
    a,
    b,
    c,
}

// resolved: struct S { mixin(generateBitFields!(B, ushort)); } (bitfields.d:138-141)
// The mixin's getter/setter pairs become these accessors over a single `ushort` store. `bitFields`
// is initialized to the generator's computed `initialValue` (2488), reproducing the `B` defaults.
class S {
    // private ushort bitFields = 2488u; (resolved init from B's field defaults)
    bitFields = 2488;

    get x(): boolean {
        return bitFieldGet(this.bitFields, 0, 1) !== 0;
    }
    set x(v: boolean) {
        this.bitFields = bitFieldSet(this.bitFields, 0, 1, v ? 1 : 0);
    }

    get y(): boolean {
        return bitFieldGet(this.bitFields, 1, 1) !== 0;
    }
    set y(v: boolean) {
        this.bitFields = bitFieldSet(this.bitFields, 1, 1, v ? 1 : 0);
    }

    get e(): E {
        return bitFieldGet(this.bitFields, 2, 3) as E;
    }
    set e(v: E) {
        this.bitFields = bitFieldSet(this.bitFields, 2, 3, v);
    }

    get z(): boolean {
        return bitFieldGet(this.bitFields, 4, 1) !== 0;
    }
    set z(v: boolean) {
        this.bitFields = bitFieldSet(this.bitFields, 4, 1, v ? 1 : 0);
    }

    get w(): number {
        return bitFieldGet(this.bitFields, 5, 255);
    }
    set w(v: number) {
        this.bitFields = bitFieldSet(this.bitFields, 5, 255, v);
    }
}

describe("bitfields.d", () => {
    test("unittest#1", () => {
        const s = new S();
        expect(!s.x).toBe(true);
        s.x = true;
        expect(s.x).toBe(true);
        s.x = false;
        expect(!s.x).toBe(true);

        s.y = true;
        expect(s.y).toBe(true);
        expect(!s.x).toBe(true);

        expect(s.e === E.c).toBe(true);
        s.e = E.a;
        expect(s.e === E.a).toBe(true);

        expect(s.z).toBe(true);
        expect(s.w === 77).toBe(true);
        s.w = 3;
        expect(s.w === 3).toBe(true);
    });
});
